     {
         var result = _formatter.BuildGreeting("Smith");

         Assert.EndsWith(",", result);
     }

     [TestMethod]
     public void BuildGreeting_DefaultTitle_ContainsName()
     {
         var result = _formatter.BuildGreeting("Smith");

         Assert.Contains("Smith", result);
     }

     [TestMethod]
     public void BuildGreeting_CustomTitle_ReturnsCorrectGreeting()
     {
         var result = _formatter.BuildGreeting("Doe", "Dr.");

         Assert.AreEqual("Dear Dr. Doe,", result);
     }

     [TestMethod]
     public void BuildGreeting_Null_ThrowsArgumentNullException()
     {
         Assert.ThrowsExactly<ArgumentNullException>(() => _formatter.BuildGreeting(null!));
     }

     [TestMethod]
     [DataRow("")]
     [DataRow("   ")]
